using System;
using System.IO;
using System.Linq;
using System.Text;
using UnityEngine;
using DragLab.Data;
using DragLab.Domain;
using DragLab.Domain.Mechanics;
using DragLab.Infrastructure;
namespace DragLab.Editor
{
    public static class IndividualEngineVerification
    {
        public static void RunStandalone(){Debug.Log("Individual engine / clutch checks: "+Run(Path.GetFullPath(Path.Combine(Application.dataPath,"../.."))));Debug.Log("OEM/parts compatibility checks: "+PartsVerification.Run(Path.GetFullPath(Path.Combine(Application.dataPath,"../.."))));}
        static void Refresh(CarSimulation car){car.mechanics.Prepare(car.state);ServiceDynamics.Prepare(car);}
        public static int Run(string root)
        {
            int count=0;var log=new StringBuilder();Action<bool,string> check=(ok,label)=>{if(!ok)throw new InvalidOperationException(label);count++;log.AppendLine("PASS: "+label);};
            var vehicles=Resources.LoadAll<VehicleDefinition>("Data/Vehicles");var catalog=new MechanicalCatalog(vehicles.Select(v=>v.spec));
            foreach(var vehicle in vehicles){var spec=vehicle.spec;string id=spec.id;int n=spec.sound.cylinders;var car=new CarSimulation(spec,vehicle.CreateStockTune(),new DriverSettings{wearMode=WearMode.None});car.state.rpm=3500;car.state.throttle=1;Refresh(car);double healthy=InductionDynamics.Torque(car.induction,car.state,3500,1),healthyFuel=FuelDynamics.Flow(car);
                check(car.state.cylinderContribution.Length==n&&car.state.cylinderContribution.All(c=>c==1),id+": healthy OEM cylinders contribute equally.");
                foreach(var category in Enum.GetValues(typeof(PartCategory)).Cast<PartCategory>().Where(EngineElements.Supported)){var p=car.mechanics.Part(category);if(p!=null)check(p.condition.elements.Length==EngineElements.Count(car.spec,car.mechanics.Definition(p)),id+": "+category+" individual layout.");}
                bool diesel=CombustionHardware.Diesel(spec);var localCategory=diesel?PartCategory.FuelSystem:spec.combustion.separateSparkPlugs?PartCategory.SparkPlugs:PartCategory.Ignition;
                var plug=car.mechanics.Part(localCategory).condition.elements.First(e=>e.role!="ignition coil"&&e.cylinder==0);plug.fault=ElementFault.Disabled;Refresh(car);
                check(!car.state.engineFailed&&!car.state.stalled&&car.state.cylinderContribution[0]==0&&car.state.cylinderContribution.Skip(1).All(c=>c==1),id+": one dead plug/injector leaves other cylinders running.");
                check(InductionDynamics.Torque(car.induction,car.state,3500,1)>0&&InductionDynamics.Torque(car.induction,car.state,3500,1)<healthy,id+": dead cylinder reduces physical torque.");
                check(diesel?FuelDynamics.Flow(car)<healthyFuel:Math.Abs(FuelDynamics.Flow(car)-healthyFuel)<healthyFuel*.03,id+": injector failure reduces fuel delivery; spark failure retains it.");
                var healthySynth=new EngineSoundSynth(new EngineSoundProfile(spec,car.tune));var faultySynth=new EngineSoundSynth(new EngineSoundProfile(spec,car.tune));var a=new float[48000];var b=new float[48000];healthySynth.Fill(a,1,48000,new EngineSoundFrame(3500,1,.8,0,1,cylinderContribution:Enumerable.Repeat(1.0,n).ToArray()));faultySynth.Fill(b,1,48000,new EngineSoundFrame(3500,1,.8,0,1,cylinderContribution:car.state.cylinderContribution));
                check(b.All(x=>!float.IsNaN(x)&&!float.IsInfinity(x))&&a.Zip(b,(x,y)=>Math.Abs(x-y)).Sum()>10,id+": missing firing event changes finite audio output.");
                plug.fault=ElementFault.None;
                if(!diesel){var coil=car.mechanics.Part(PartCategory.Ignition).condition.elements.First(e=>e.role=="ignition coil");coil.fault=ElementFault.Disabled;Refresh(car);
                check(EngineElements.Ignition(spec)==IgnitionTopology.Distributor?car.state.stalled:!car.state.stalled&&car.state.cylinderContribution.Count(c=>c==0)==1,id+": shared/individual coil fault scope.");
                coil.fault=ElementFault.None;car.state.stalled=false;Refresh(car);}
                else {Refresh(car);check(car.mechanics.Part(PartCategory.Ignition)==null&&car.mechanics.Part(PartCategory.SparkPlugs)==null,id+": compression ignition uses no coils or spark plugs.");}
                var injector=car.mechanics.Part(PartCategory.FuelSystem).condition.elements.FirstOrDefault();if(injector!=null){injector.fault=ElementFault.Disabled;Refresh(car);check(car.state.cylinderFuelFactor<1&&car.state.cylinderCombustionFactor<1&&!car.state.stalled,id+": injector stops local fuel only.");check(FuelDynamics.Flow(car)<healthyFuel,id+": failed injector reduces flow.");injector.fault=ElementFault.None;}
                var valve=car.mechanics.Part(PartCategory.Valves).condition.elements.First(e=>e.cylinder==0);valve.fault=ElementFault.StuckOpen;valve.severity=.8f;Refresh(car);check(car.state.cylinderContribution[0]<.25&&!car.state.engineFailed,id+": stuck valve reduces compression.");valve.fault=ElementFault.None;
                var spring=car.mechanics.Part(PartCategory.ValveSprings).condition.elements.First(e=>e.cylinder==0);spring.fault=ElementFault.WeakSpring;spring.severity=1;car.state.rpm=spec.idleRpm;Refresh(car);double idle=car.state.cylinderContribution[0];car.state.rpm=spec.redlineRpm;Refresh(car);check(car.state.cylinderContribution[0]<idle&&car.state.individualValveFloat>0&&!car.state.engineFailed,id+": spring fault depends on RPM.");spring.fault=ElementFault.None;valve.fault=ElementFault.DroppedValve;Refresh(car);check(car.state.engineFailed,id+": dropped valve is destructive.");
                var profile=PlayerProfile.New(DateTime.UtcNow.Ticks);profile.cars.Clear();profile.cars.Add(new OwnedCar{vehicleId=id,tune=vehicle.CreateStockTune()});profile.selectedVehicleId=id;profile.cash=100000;MechanicsOwnership.Ensure(profile,catalog);var owner=profile.SelectedCar;var pistons=profile.parts.First(p=>p.ownerId==owner.engineAssemblyId&&p.slot=="Pistons");var old=pistons.condition.elements[0];old.health=.1f;EngineElementService.RefreshAggregate(pistons.condition);var neighbour=pistons.condition.elements[1].Copy();int cash=profile.cash;int unit=EngineElementService.Price(catalog.Find(pistons.definitionId),pistons.condition);check(unit<catalog.Find(pistons.definitionId).price,id+": single piston cheaper than full set.");
                string oldId=old.id;EngineElementService.Replace(profile,owner.instanceId,pistons.instanceId,oldId);check(profile.cash==cash-unit&&pistons.condition.elements[0].health==1&&pistons.condition.elements[1].id==neighbour.id&&pistons.condition.elements[1].health==neighbour.health&&profile.looseEngineElements.Any(e=>e.element.id==oldId&&e.element.health==.1f),id+": replacement retains original and neighbours.");
                var loaded=JsonUtility.FromJson<PlayerProfile>(JsonUtility.ToJson(profile));MechanicsOwnership.Ensure(loaded,catalog);check(MechanicsOwnership.Validate(loaded,catalog)==null&&loaded.looseEngineElements.Count==1,id+": individual inventory survives load.");
                var installed=loaded.parts.First(p=>p.instanceId==pistons.instanceId);EngineElementService.Replace(loaded,owner.instanceId,installed.instanceId,installed.condition.elements[0].id,oldId);check(installed.condition.elements[0].health==.1f&&loaded.looseEngineElements.Count==1,id+": worn original reusable without renewal.");
                var checkpoint=new RunCheckpoint{runId="no-local-heal",ownedVehicleId=owner.instanceId,tick=1,components=loaded.parts.Where(p=>p.ownerId==owner.engineAssemblyId).Select(p=>p.Copy()).ToList()};checkpoint.components.First(p=>p.instanceId==installed.instanceId).condition.elements[0].health=1;bool rejected=false;try{MechanicsTransactions.ApplyCheckpoint(loaded,checkpoint);}catch(InvalidOperationException){rejected=true;}check(rejected,id+": checkpoint cannot heal local damage.");
                var reservationOwner=loaded.SelectedCar;long now=DateTime.UtcNow.Ticks;var quote=EngineRebuilds.Quote(loaded,reservationOwner,now);cash=loaded.cash;EngineRebuilds.Start(loaded,reservationOwner.instanceId,now);var job=reservationOwner.engineRebuild;check(loaded.cash==cash-quote.paidPrice&&job.readyUtcTicks>now&&!MechanicsOwnership.Resolve(loaded,reservationOwner,catalog).Drivable,id+": rebuild paid/reserved.");
                rejected=false;try{EngineRebuilds.Collect(loaded,reservationOwner.instanceId,job.id,now);}catch(InvalidOperationException){rejected=true;}check(rejected,id+": early collection denied.");
                rejected=false;try{PartOperations.Remove(loaded,reservationOwner.instanceId,PartCategory.Pistons);}catch(InvalidOperationException){rejected=true;}check(rejected,id+": reserved parts locked.");
                var persisted=JsonUtility.FromJson<PlayerProfile>(JsonUtility.ToJson(loaded));MechanicsOwnership.Ensure(persisted,catalog);var reserved=persisted.SelectedCar;check(reserved.engineRebuild.id==job.id&&reserved.engineRebuild.readyUtcTicks==job.readyUtcTicks,id+": paid deadline survives offline reload.");
                var tires=persisted.parts.First(p=>p.ownerId==reserved.instanceId&&p.slot=="Tires");tires.condition.tires[0].health=.4f;tires.condition.tires[0].consumedLife=.6;TireDynamics.SyncSummary(tires.condition);double fuel=reserved.fuel.litres;string tune=JsonUtility.ToJson(reserved.tune);EngineRebuilds.Collect(persisted,reserved.instanceId,job.id,job.readyUtcTicks);check(reserved.engineRebuild==null&&tires.condition.tires[0].health==.4f&&tires.condition.health==1&&reserved.fuel.litres==fuel&&JsonUtility.ToJson(reserved.tune)==tune,id+": collection preserves unrelated hardware/fuel/tune.");check(MechanicsOwnership.Validate(persisted,catalog)==null,id+": collection validates / "+MechanicsOwnership.Validate(persisted,catalog));
                rejected=false;try{EngineRebuilds.Collect(persisted,reserved.instanceId,job.id,job.readyUtcTicks);}catch(InvalidOperationException){rejected=true;}check(rejected,id+": repeated collection denied.");
                foreach(var clutch in catalog.parts.Where(p=>p.id.StartsWith(id+"/Clutch/"))){var map=catalog.Recipe(id);map[PartCategory.Clutch]=clutch.id;map[PartCategory.Gearbox]=id+"/Gearbox/Manual";var resolved=catalog.Resolve(id,map,vehicle.CreateStockTune());var test=new CarSimulation(resolved.spec,resolved.tune,new DriverSettings{wearMode=WearMode.Full});Refresh(test);var p=test.mechanics.Part(PartCategory.Clutch);check(clutch.clutchPlateCount>=1&&test.state.clutchCapacityFactor>0,id+": "+clutch.id+" coupling works.");if(clutch.clutchEnvironment==ClutchEnvironment.Wet){double filled=test.state.clutchCapacityFactor;p.condition.clutchOilLitres=0;Refresh(test);check(test.state.clutchCapacityFactor<filled&&test.state.clutchOilFactor==0,id+": wet bath affects capacity separately.");}check(!double.IsNaN(ClutchHardware.Engagement(clutch,.6,3500)),id+": finite engagement.");}
                var dryMap=catalog.Recipe(id);dryMap[PartCategory.Gearbox]=id+"/Gearbox/Manual";dryMap[PartCategory.Clutch]=id+"/Clutch/DryTwinOrganic";var dryBuild=catalog.Resolve(id,dryMap,vehicle.CreateStockTune());dryMap[PartCategory.Clutch]=id+"/Clutch/WetMultiOrganic";var wetBuild=catalog.Resolve(id,dryMap,vehicle.CreateStockTune());
                var dryCar=new CarSimulation(dryBuild.spec,dryBuild.tune,new DriverSettings());var wetCar=new CarSimulation(wetBuild.spec,wetBuild.tune,new DriverSettings());var dryPart=dryCar.mechanics.Part(PartCategory.Clutch);var wetPart=wetCar.mechanics.Part(PartCategory.Clutch);dryPart.condition.temperatureC=wetPart.condition.temperatureC=100;dryCar.state.clutchFrictionPowerW=wetCar.state.clutchFrictionPowerW=10000;dryCar.mechanics.Tick(dryCar,1,0,0);wetCar.mechanics.Tick(wetCar,1,0,0);check(wetPart.condition.temperatureC<dryPart.condition.temperatureC,id+": wet oil bath rejects more equal-work clutch heat.");
                double fullMass=wetCar.mass.TranslatingKg;wetPart.condition.clutchOilLitres=0;wetCar.RefreshFluidMass();check(Math.Abs(fullMass-wetCar.mass.TranslatingKg-2*.86)<1e-6,id+": missing clutch oil removes its own liquid mass exactly once.");wetPart.condition.clutchOilLitres=2;wetPart.condition.leakSeverity=.5;double beforeOil=wetPart.condition.clutchOilLitres;wetCar.mechanics.Tick(wetCar,1,0,0);check(wetPart.condition.clutchOilLitres<beforeOil,id+": injected clutch leak drains dedicated bath.");wetCar.driver.fluidDepletion=ConsumptionMode.None;beforeOil=wetPart.condition.clutchOilLitres;wetCar.mechanics.Tick(wetCar,1,0,0);check(wetPart.condition.clutchOilLitres==beforeOil,id+": fluid-depletion assistance also covers clutch bath.");double retainedBath=wetPart.condition.clutchOilLitres;wetCar.mechanics.ResetWear(wetCar.state);check(wetCar.mechanics.Part(PartCategory.Clutch).condition.clutchOilLitres==retainedBath,id+": wear reset does not refill dedicated clutch oil.");
                if(!diesel){var pairedSpec=spec.Copy();pairedSpec.ignitionTopology=IgnitionTopology.WastedSpark;var paired=new CarSimulation(pairedSpec,vehicle.CreateStockTune(),new DriverSettings());paired.mechanics.Part(PartCategory.Ignition).condition.elements.First(e=>e.role=="ignition coil").fault=ElementFault.Disabled;Refresh(paired);check(paired.state.cylinderContribution.Count(c=>c==0)==2,id+": wasted-spark coil affects exactly its pair.");}
                var valvePart=profile.parts.First(p=>p.ownerId==owner.engineAssemblyId&&p.slot=="Valves");var singleValve=valvePart.condition.elements[0];singleValve.fault=ElementFault.StuckOpen;singleValve.severity=1;string neighbourValve=valvePart.condition.elements[1].id;EngineElementService.Replace(profile,owner.instanceId,valvePart.instanceId,singleValve.id);check(valvePart.condition.elements[0].fault==ElementFault.None&&valvePart.condition.elements[1].id==neighbourValve,id+": singular valve repair retains other valve identities.");
                var localWear=new EngineElement{health=1,id="wear",role="piston",cylinder=0,valve=-1};var wearSet=new PartInstance{condition=new ComponentCondition{elements=new[]{localWear}}};for(int tick=0;tick<10000;tick++)EngineElements.Wear(wearSet,1e-8);check(localWear.health<1,id+": sub-float wear accumulates instead of disappearing.");
                check(ClutchHardware.Engagement(catalog.Find(id+"/Clutch/DryCentrifugal"),0,1000)==0&&ClutchHardware.Engagement(catalog.Find(id+"/Clutch/DryCentrifugal"),0,3500)>0,id+": centrifugal RPM clamp.");
                var snap=new RunSnapshot{vehicle=spec.Copy(),tune=vehicle.CreateStockTune(),driving=new DriverSettings{wearMode=WearMode.Full}};var session=new PhysicalDrivingSession(snap);session.car.mechanics.Part(localCategory).condition.elements[0].fault=ElementFault.Disabled;session=session.ContinueRecording();for(int i=0;i<600;i++)session.Step(new TickInput{tick=i,neutral=i<120,input=new DriverInput{throttle=i<450?.8:0,shiftUp=i==120||i==350}});var replay=PhysicalDrivingSession.Replay(JsonUtility.FromJson<RunSnapshot>(JsonUtility.ToJson(session.snapshot)));check(session.Csv()==replay.Csv()&&session.car.state.cylinderContribution.SequenceEqual(replay.car.state.cylinderContribution),id+": exact local-fault replay through shifts/coast.");
            }
            var folder=Path.Combine(root,"reports/individual-engine");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"verification.txt"),log+"TOTAL "+count);return count;
        }
    }
